	"math"
	"strconv"
	"strings"
)

func main() {
	var n int
	fmt.Scan(&n)

	var aLine string
	fmt.Scan(&aLine)
	aStr := strings.Fields(aLine)
	a := make([]int, len(aStr))
	for i, s := range aStr {
		v, _ := strconv.Atoi(s)
		a[i] = v
	}

	var bLine string
	fmt.Scan(&bLine)
	bStr := strings.Fields(bLine)
	b := make([]int, len(bStr))
	for i, s := range bStr {
		v, _ := strconv.Atoi(s)
		b[i] = v
	}

	rez := 0.0
	for i := range a {
		if a[i] == 1 && b[i] == 0 {
			rez += 1
		}
	}

	aSum := 0
	for _, v := range a {
		aSum += v
	}

	bSum := 0
	for _, v := range b {
		bSum += v
	}

	var result int
	if aSum > bSum {
		result = 1
	} else if rez == 0 || aSum == 0 || (aSum == n && bSum == n) {
		result = -1
	} else {
		result = int(math.Ceil(float64(bSum-aSum+1) / rez)) + 1
