	"strconv"
	"strings"
)

func main() {
	var n int
	fmt.Scan(&n)

	var aLine, bLine string
	fmt.Scan(&aLine)
	fmt.Scan(&bLine)

	a := parseSlice(aLine)
	b := parseSlice(bLine)

	var rez float64
	for i, x := range a {
		if x == 1 && b[i] == 0 {
			rez += 1
		}
	}

	aSum := sum(a)
	bSum := sum(b)

	var result int
	if aSum > bSum {
		result = 1
	} else if rez == 0 || aSum == 0 || (aSum == n && bSum == n) {
		result = -1
	} else {
		result = int(math.Ceil(float64(bSum-aSum+1)/rez)) + 1
	}

	fmt.Println(result)
}

func parseSlice(s string) []int {
	parts := strings.Fields(s)
	res := make([]int, len(parts))
	for i, p := range parts {
		v, _ := strconv.Atoi(p)
		res[i] = v
	}
	return res
}

func sum(a []int) int {
	s := 0
	for _, v := range a {
		s += v
	}
	return s
}
